static int checks=0;
static void check(bool ok,const char* text){if(!ok)throw std::runtime_error(text);++checks;std::cout<<"PASS "<<text<<std::endl;}
static void pump(int ms){auto until=monotonic()+ms*.001;while(monotonic()<until){MSG m;while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}Thread::sleep(1);}}
static void wait(std::function<bool()> f,const char* text){auto until=monotonic()+4;while(!f()&&monotonic()<until)pump(10);check(f(),text);}
static void position(const Id& id,double value){service()->injectPosition(id,value);wait([&]{return std::abs(service()->snapshot().motors[id].position-value)<.1;},"fake encoder stimulus received");}
static void motion(std::shared_ptr<MidnightBehaviour> b,const Id& motor,double end=.0,double duration=.12){b->motor->select(motor);b->duration->setValue(duration);b->startAngle->setValue(0);b->target->setValue(end);b->playCurve->setValue(true);}
